const incoming = $input.first().json;
const body = incoming.body ?? incoming;
const message = String(body.message ?? '').trim();
const email = String(body.customer_email ?? '').trim().toLowerCase();
const rawUrl = String(body.customer_url ?? '').trim();

if (!message || message.length > 2000) {
  throw new Error('Message must contain 1 to 2000 characters.');
}
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  throw new Error('A valid customer email is required.');
}

const customerUrl = new URL(rawUrl);
const allowedHosts = new Set(['support.example.org', 'status.example.org']);
if (customerUrl.protocol !== 'https:' || !allowedHosts.has(customerUrl.hostname)) {
  throw new Error('Customer URL is outside the approved destination list.');
}

// Enforce the real request quota at the gateway or a shared datastore.
// This fixture keeps the boundary visible but does not claim in-memory rate limiting.
return [{
  json: {
    request_id: String(body.request_id ?? crypto.randomUUID()),
    message,
    customer_email: email,
    customer_url: customerUrl.toString(),
    policy: {
      max_model_calls: 1,
      approval_required: true
    }
  }
}];

const raw = $input.first().json;
const parsed = typeof raw.output === 'string' ? JSON.parse(raw.output) : raw.output;
const allowed = new Set(['subject', 'body', 'risk']);
for (const key of Object.keys(parsed ?? {})) {
  if (!allowed.has(key)) throw new Error(`Unexpected model field: ${key}`);
}
const subject = String(parsed?.subject ?? '').trim().slice(0, 120);
const body = String(parsed?.body ?? '').trim().slice(0, 4000);
const risk = String(parsed?.risk ?? '').trim().toLowerCase();
if (!subject || !body || !['low', 'medium', 'high'].includes(risk)) {
  throw new Error('Model output does not match the approved schema.');
}
return [{ json: { ...$input.first().json, draft: { subject, body, risk } } }];
